package fr.cercle.sixtuiles;import android.app.Activity;import android.os.Bundle;import android.view.*;import android.graphics.*;import android.content.*;import java.util.*;
public class MainActivity extends Activity{Game game;public void onCreate(Bundle b){super.onCreate(b);game=new Game(this);setContentView(game);}public void onPause(){super.onPause();game.paused=true;game.save();}public void onResume(){super.onResume();}
class Game extends View{Engine e;Paint p=new Paint(3);float scale=1,ox,oy;boolean paused;int best;final int bg=Color.rgb(13,23,29),panel=Color.rgb(25,42,49),fg=Color.rgb(237,232,215),muted=Color.rgb(155,178,181),gold=Color.rgb(231,180,105);int[] colors={Color.rgb(231,180,105),Color.rgb(132,194,164),Color.rgb(155,182,231)};
Game(Context c){super(c);best=getPreferences(0).getInt("best",0);e=new Engine(1,System.nanoTime());try{String s=getPreferences(0).getString("run","");if(!s.isEmpty()){String[] a=s.split(";");long seed=Long.parseLong(a[0]);Engine restored=new Engine(1,seed);for(int i=1;i<a.length;i++){String[] z=a[i].split(",");if(z[0].equals("g")){for(int j=0;j<4;j++)restored.guess[j]=Integer.parseInt(z[j+1]);restored.submit();}else if(z[0].equals("t")){restored.selected=Integer.parseInt(z[1]);restored.rotation=Integer.parseInt(z[2]);restored.px=Integer.parseInt(z[3]);restored.py=Integer.parseInt(z[4]);restored.placeTile();}else if(z[0].equals("o")){restored.selected=Integer.parseInt(z[1]);restored.rotation=Integer.parseInt(z[2]);restored.px=Integer.parseInt(z[3]);restored.py=Integer.parseInt(z[4]);restored.placeObject();}else if(z[0].equals("s"))restored.skip();}e=restored;log=s;}else fresh();}catch(Exception ex){fresh();}setContentDescription("Six Tuiles, jeu hors ligne");}String log="";void fresh(){long seed=System.nanoTime();e=new Engine(1,seed);log=""+seed;}void save(){getPreferences(0).edit().putInt("best",best).putString("run",log).apply();}
void text(Canvas c,String s,float x,float y,int size,int col){p.setColor(col);p.setStyle(Paint.Style.FILL);p.setTypeface(Typeface.create("sans-serif",0));p.setTextSize(size);c.drawText(s,x,y,p);}void box(Canvas c,float x,float y,float w,float h,int col){p.setColor(col);p.setStyle(Paint.Style.FILL);c.drawRoundRect(x,y,x+w,y+h,14,14,p);}void line(Canvas c,float x,float y,float a,float b,int col,int width){p.setColor(col);p.setStrokeWidth(width);c.drawLine(x,y,a,b,p);}void dot(Canvas c,float x,float y,float r,int col){p.setColor(col);c.drawCircle(x,y,r,p);}void button(Canvas c,String s,float x,float y,float w,int col){box(c,x,y,w,88,col);text(c,s,x+16,y+53,23,col==gold?bg:fg);}void wrap(Canvas c,String s,float y){String l="";int row=0;p.setTextSize(22);for(String w:s.split(" ")){if(p.measureText(l+w)>620){text(c,l,40,y+row*30,22,fg);row++;l="";}l+=w+" ";}text(c,l,40,y+row*30,22,fg);}
void tile(Canvas c,int m,float x,float y,float size,int col){box(c,x+3,y+3,size-6,size-6,panel);for(int d=0;d<4;d++)if((m&(1<<d))!=0)line(c,x+size/2,y+size/2,x+size/2+new int[]{0,1,0,-1}[d]*size/2,y+size/2+new int[]{-1,0,1,0}[d]*size/2,col,10);dot(c,x+size/2,y+size/2,9,col);}
protected void onDraw(Canvas c){if(e.over&&e.score>best){best=e.score;save();}scale=Math.min(getWidth()/720f,getHeight()/1280f);ox=(getWidth()-720*scale)/2;oy=(getHeight()-1280*scale)/2;c.drawColor(bg);c.save();c.translate(ox,oy);c.scale(scale,scale);text(c,"JEUX COURTS / VERSION 0.1.0",30,45,18,muted);text(c,"Six Tuiles",30,105,45,fg);button(c,"PAUSE",510,130,180,panel);text(c,"SCORE "+e.score+" · RECORD "+best,30,185,22,gold);
if(e.mode==0){text(c,"SIX ESSAIS · CHIFFRES 1 À 6 SANS DOUBLON",30,260,21,muted);for(int r=0;r<6;r++){int[] g=r<e.history.size()?e.history.get(r):r==e.turn&&!e.over?e.guess:new int[4];for(int j=0;j<4;j++){box(c,35+j*112,290+r*92,96,76,r==e.turn&&j==e.focus&&!e.over?colors[1]:panel);text(c,g[j]==0?"·":""+g[j],69+j*112,342+r*92,32,fg);}if(r<e.feedback.size()){int[] f=e.feedback.get(r);text(c,f[0]+" placés",495,320+r*92,21,colors[1]);text(c,f[1]+" ailleurs",495,350+r*92,21,gold);}}for(int j=0;j<6;j++)button(c,""+(j+1),30+j*112,905,98,panel);text(c,"Vert : bonne place · Or : présent ailleurs",30,1035,23,muted);}
if(e.mode==1){text(c,"TUILE "+Math.min(6,e.turn+1)+" / 6 · BONUS DORÉS +40",30,260,24,gold);for(int y=0;y<4;y++)for(int x=0;x<4;x++){tile(c,e.board[y][x],100+x*130,350+y*130,130,colors[1]);if((x==1&&y==1)||(x==2&&y==2))dot(c,118+x*130,368+y*130,7,gold);if(x==e.px&&y==e.py){tile(c,e.tile(),100+x*130,350+y*130,130,gold);}}text(c,"ENTRÉE",4,690,18,colors[1]);text(c,"SORTIE",625,425,18,colors[1]);for(int i=0;i<2;i++){box(c,100+i*280,915,240,120,e.selected==i?gold:panel);tile(c,e.selected==i?e.tile():e.offers[i],165+i*280,922,105,e.selected==i?bg:fg);}}
if(e.mode==2){text(c,"CHOIX "+Math.min(8,e.turn+1)+" / 8 · TROIS OBJETS = +40",30,260,23,gold);for(int y=0;y<4;y++)for(int x=0;x<4;x++)box(c,100+x*130+3,350+y*130+3,124,124,e.board[y][x]<0?panel:colors[e.board[y][x]]);if(e.px>=0){int id=e.offers[e.selected]/3;for(int[] a:Engine.shape(id,e.rotation)){int x=e.px+a[0],y=e.py+a[1];if(x<4&&y<4)box(c,100+x*130+12,350+y*130+12,106,106,e.fits(id,e.rotation,e.px,e.py)?gold:Color.rgb(160,75,75));}}for(int i=0;i<3;i++){int o=e.offers[i],id=o/3,fam=o%3;box(c,30+i*230,910,210,145,e.selected==i?Color.rgb(61,78,80):panel);for(int[] a:Engine.shape(id,e.selected==i?e.rotation:0))box(c,48+i*230+a[0]*28,925+a[1]*28,24,24,colors[fam]);text(c,Engine.VALUES[id]+" pts",135+i*230,950,20,fg);text(c,e.anyFit(id)?"PLAÇABLE":"TROP GRAND",45+i*230,1038,17,muted);}text(c,"COLLECTIONS  "+e.counts[0]+" or · "+e.counts[1]+" jade · "+e.counts[2]+" bleu",35,875,21,muted);}
wrap(c,e.message,1100);if(e.mode==0){button(c,"EFFACER",30,1180,310,panel);button(c,"ESSAYER",360,1180,330,gold);}else{button(c,"TOURNER",30,1180,210,panel);button(c,e.mode==1?"REFAIRE":"PASSER",255,1180,210,panel);button(c,"POSER",480,1180,210,gold);}if(e.over){box(c,55,430,610,420,bg);text(c,e.won?"PARTIE RÉUSSIE":"FIN DE PARTIE",90,510,34,gold);text(c,e.score+" points",90,595,48,fg);if(e.mode==0)text(c,"CODE : "+Arrays.toString(e.secret),90,660,28,muted);else wrap(c,e.message,665);button(c,"REJOUER",90,720,540,gold);}if(paused){box(c,55,430,610,360,bg);text(c,"PAUSE",95,520,40,fg);text(c,"Ta partie est enregistrée.",95,585,27,muted);button(c,"REPRENDRE",95,655,530,gold);}c.restore();}
public boolean onTouchEvent(MotionEvent ev){if(ev.getActionMasked()!=0)return true;float x=(ev.getX()-ox)/scale,y=(ev.getY()-oy)/scale;if(paused){paused=false;invalidate();return true;}if(e.over){if(y>720&&y<820){fresh();save();invalidate();}return true;}if(x>500&&y>125&&y<225){paused=true;save();invalidate();return true;}if(e.mode==0){if(y>290&&y<842&&x>=35&&x<483){int row=(int)((y-290)/92);if(row==e.turn)e.focus=Math.min(3,(int)((x-35)/112));}if(y>905&&y<995&&x>=30&&x<702){int val=(int)((x-30)/112)+1;e.guess[e.focus]=val;e.focus=(e.focus+1)%4;}if(y>1180){if(x<350)e.guess[e.focus]=0;else{String entry="g";for(int a:e.guess)entry+=","+a;if(e.submit())log+=";"+entry;}}}else{if(y>350&&y<870&&x>=100&&x<620){e.px=(int)((x-100)/130);e.py=(int)((y-350)/130);}if(y>910&&y<1060){if(e.mode==1&&x>=100&&x<620){e.selected=x<380?0:1;e.rotation=0;}if(e.mode==2&&x>=30&&x<720){e.selected=Math.min(2,(int)((x-30)/230));e.rotation=0;}}if(y>1180){if(x<240)e.rotation=(e.rotation+1)%4;else if(x<475){if(e.mode==2){e.skip();log+=";s";}else fresh();}else{String entry=(e.mode==1?"t":"o")+","+e.selected+","+e.rotation+","+e.px+","+e.py;boolean ok=e.mode==1?e.placeTile():e.placeObject();if(ok)log+=";"+entry;else e.message="Choisis une case libre où la pièce rentre.";}}}save();invalidate();return true;}
}}
